    64|export function durableKeyForFile(file: string): string {
    65|  const normalized = file.split(path.sep).join('/');
    66|  const marker = 'logs/audit/';
    67|  const idx = normalized.indexOf(marker);
    68|  if (idx >= 0) return normalized.slice(idx + marker.length);
    69|  // Fallback: last two segments keep it readable and unique enough per store.
    70|  const parts = normalized.split('/').filter(Boolean);
    71|  return parts.slice(-2).join('/') || normalized;
